import express from 'express';
import { createClient } from '@libsql/client';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const db = createClient({
  url: process.env.LIBSQL_URL,
  authToken: process.env.LIBSQL_AUTH_TOKEN
});

// Middleware: rate limit by IP
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = (requestCounts.get(ip) || 0) + 1;
  requestCounts.set(ip, count);
  if (count > 100) return res.status(429).json({ error: 'Rate limited' });
  setTimeout(() => requestCounts.set(ip, (requestCounts.get(ip) || 1) - 1), 60000);
  next();
});

// User registration
app.post('/api/register', async (req, res) => {
  try {
    const { username, email, password } = req.body;
    if (!username || !email || !password) {
      return res.status(400).json({ error: 'Missing fields' });
    }
    // Basic validation
    if (username.length > 64 || email.length > 128) {
      return res.status(400).json({ error: 'Field too long' });
    }
    const hash = crypto.createHash('sha256').update(password).digest('hex');
    const id = crypto.randomUUID();
    await db.execute({
      sql: `INSERT INTO users (id, username, email, password_hash, role) VALUES (?, ?, ?, ?, 'user')`,
      args: [id, username, email, hash]
    });
    res.json({ id, username });
  } catch (err) {
    res.status(500).json({ error: 'Registration failed', detail: err.message });
  }
});

// Login endpoint
app.post('/api/login', async (req, res) => {
  try {
    const { username, password } = req.body;
    const hash = crypto.createHash('sha256').update(password || '').digest('hex');
    const result = await db.execute({
      sql: `SELECT id, username, role FROM users WHERE username = ? AND password_hash = ?`,
      args: [username, hash]
    });
    if (result.rows.length === 0) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }
    const token = crypto.randomBytes(32).toString('hex');
    await db.execute({
      sql: `INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, datetime('now', '+24 hours'))`,
      args: [token, result.rows[0].id]
    });
    res.json({ token, user: result.rows[0] });
  } catch (err) {
    res.status(500).json({ error: 'Login failed' });
  }
});

// Vulnerable product search - string concatenation in ORDER BY
app.get('/api/products', async (req, res) => {
  try {
    const { category, sort, direction } = req.query;
    const dir = direction === 'desc' ? 'DESC' : 'ASC';
    // Developer note: parameterized the WHERE but forgot ORDER BY
    let query = `SELECT id, name, price, stock, category FROM products WHERE category = ?`;

    // Sort field is user-controlled and concatenated directly
    if (sort) {
      query += ` ORDER BY ${sort} ${dir}`;
    } else {
      query += ` ORDER BY name ASC`;
    }

    query += ` LIMIT 50`;

    const result = await db.execute({
      sql: query,
      args: [category || 'all']
    });
    res.json({ products: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Search failed', query_error: err.message });
  }
});

// Admin inventory update (no auth check - another vuln)
app.put('/api/products/:id/stock', async (req, res) => {
  try {
    const { stock } = req.body;
    await db.execute({
      sql: `UPDATE products SET stock = ?, updated_at = datetime('now') WHERE id = ?`,
      args: [stock, req.params.id]
    });
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'Update failed' });
  }
});

app.listen(process.env.PORT || 8080);
